import 'package:flutter/material.dart';
import '../../services/api_service.dart';
class PaymentsScreen extends StatefulWidget{const PaymentsScreen({super.key});@override State<PaymentsScreen> createState()=>_PaymentsScreenState();}
class _PaymentsScreenState extends State<PaymentsScreen>{List items=[],students=[],subscriptions=[];bool loading=true;List<dynamic> list(dynamic x)=>x is List?List<dynamic>.from(x):x is Map&&x['data'] is List?List<dynamic>.from(x['data']):[];@override void initState(){super.initState();load();}void msg(Object e)=>ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString().replaceFirst('Exception: ',''))));
Future<void> load()async{try{final r=await Future.wait([ApiService.get('payments'),ApiService.get('students'),ApiService.get('subscriptions')]);if(mounted)setState((){items=list(r[0]);students=list(r[1]);subscriptions=list(r[2]);loading=false;});}catch(e){if(mounted){setState(()=>loading=false);msg(e);}}}
Future<void> add()async{if(students.isEmpty){msg(Exception('أضف طالبًا أولًا'));return;}int studentId=students.first['id'];int? subscriptionId;final amount=TextEditingController(),date=TextEditingController(text:DateTime.now().toIso8601String().substring(0,10)),method=TextEditingController(text:'نقدي');final k=GlobalKey<FormState>();final ok=await showDialog<bool>(context:context,builder:(c)=>StatefulBuilder(builder:(c,setD){final subs=subscriptions.where((x)=>x['student_id']==studentId||x['student']?['id']==studentId).toList();if(subscriptionId!=null&&!subs.any((x)=>x['id']==subscriptionId))subscriptionId=null;return AlertDialog(title:const Text('إضافة دفعة'),content:Form(key:k,child:Column(mainAxisSize:MainAxisSize.min,children:[DropdownButtonFormField<int>(value:studentId,decoration:const InputDecoration(labelText:'الطالب'),items:students.map((x)=>DropdownMenuItem(value:x['id'] as int,child:Text('${x['name']}'))).toList(),onChanged:(v){if(v!=null)setD(()=>studentId=v);}),DropdownButtonFormField<int?>(value:subscriptionId,decoration:const InputDecoration(labelText:'الاشتراك عند الحاجة'),items:[const DropdownMenuItem<int?>(value:null,child:Text('بدون اشتراك')),...subs.map((x)=>DropdownMenuItem<int?>(value:x['id'] as int,child:Text('${x['subject']} • ${x['amount']}')))],onChanged:(v)=>setD(()=>subscriptionId=v)),TextFormField(controller:amount,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'المبلغ'),validator:(v)=>double.tryParse(v??'')==null?'مبلغ غير صحيح':null),TextFormField(controller:date,decoration:const InputDecoration(labelText:'التاريخ YYYY-MM-DD')),TextFormField(controller:method,decoration:const InputDecoration(labelText:'طريقة الدفع'))])),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('إلغاء')),FilledButton(onPressed:()=>k.currentState!.validate()?Navigator.pop(c,true):null,child:const Text('حفظ'))]));if(ok==true)try{await ApiService.post('payments',{'student_id':studentId,'subscription_id':subscriptionId,'amount':double.parse(amount.text),'paid_on':date.text.trim(),'method':method.text.trim()});await load();}catch(e){msg(e);}finally{amount.dispose();date.dispose();method.dispose();}}
@override Widget build(BuildContext context){return Scaffold(appBar:AppBar(title:const Text('المدفوعات'),actions:[IconButton(onPressed:load,icon:const Icon(Icons.refresh))]),floatingActionButton:FloatingActionButton(onPressed:add,child:const Icon(Icons.add)),body:loading?const Center(child:CircularProgressIndicator()):RefreshIndicator(onRefresh:load,child:ListView.builder(padding:const EdgeInsets.all(16),itemCount:items.length,itemBuilder:(_,i){final x=items[i],s=x['student'],sub=x['subscription'];return Card(child:ListTile(leading:const CircleAvatar(child:Icon(Icons.payments)),title:Text('${s?['name']??'طالب'}'),subtitle:Text('الاشتراك: ${sub?['subject']??'غير مرتبط'}\n${x['paid_on']??''} • ${x['method']??''}'),isThreeLine:true,trailing:Text('${x['amount']??0}')));})));}}
